#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// I2C manzili odatda 0x27 yoki 0x3F bo'ladi. Displey o'lchami: 20 ustun, 4 qator.
LiquidCrystal_I2C lcd(0x27, 20, 4); 

// Yuguradigan matn (oxiriga bo'sh joylar qo'shiladi)
String scrollText = "Assalomu alaykum! Arduino 2004 LCD displeyida yuguruvchi satr loyihasi. ";

void setup() {
  lcd.init();          // Displeyni ishga tushirish
  lcd.backlight();     // Orqa yoritishni (podsvetka) yoqish

  // Turg'un matnlar (xohlasangiz boshqa qatorlarga yozishingiz mumkin)
  lcd.setCursor(0, 0);
  lcd.print("====================");

  lcd.setCursor(0, 2);
  lcd.print("Status: Faol");

  lcd.setCursor(0, 3);
  lcd.print("====================");
}

void loop() {
  // Matnni 1-qatorda (index 1) o'ngdan chapga yugurtirish
  for (int i = 0; i < scrollText.length(); i++) {
    lcd.setCursor(0, 1); // 2-qator, 1-ustun

    // 20 ta belgidan iborat qismni kesib olish
    String displayChunk = scrollText.substring(i, i + 20);

    // Agar satr oxiriga yetib qolsa, boshidan to'ldirish
    if (displayChunk.length() < 20) {
      displayChunk += scrollText.substring(0, 20 - displayChunk.length());
    }

    lcd.print(displayChunk);
    delay(250); // Tezlikni sozlash (qancha kichik bo'lsa, shuncha tez harakatlanadi)
  }
}
